#!/usr/bin/env python3
"""Build the lab book: render docs/labbook/index.html from the Lean sources.

Each code cell is anchored to a definition or theorem in formal/uvrr-lean and
read straight from the working tree, so the artefact follows the sources. The
per-line English readings are lab-book commentary keyed to the exact line they
read; when an anchored line changes, the build fails until its anchor is
updated, so the book can never silently drift from the kernel-checked text.
"""

import html
import json
import re
import subprocess
import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
SRC = ROOT / "formal" / "uvrr-lean" / "UVRR"
OUT = ROOT / "docs" / "labbook" / "index.html"

KEYWORDS = frozenset(['absurd', 'apply', 'by', 'classical', 'def', 'else', 'exact', 'fun', 'have', 'if', 'intro', 'match', 'noncomputable', 'omega', 'rcases', 'refine', 'rfl', 'rw', 'simp', 'then', 'theorem', 'unfold', 'with'])

TOKEN = re.compile(
    r"\b(?:" + "|".join(sorted(KEYWORDS, key=len, reverse=True)) + r")\b"
    r"|\b[A-Z][A-Za-z0-9_.]*"
    r"|(?<![\w.])\d+")

