def cls(token):
    if token in KEYWORDS:
        return "kw"
    if token.isdigit():
        return "num"
    return "ty"


def highlight(line):
    stripped = line.strip()
    if not stripped:
        return "&nbsp;"
    esc = html.escape(line, quote=False)
    if stripped.startswith("/--"):
        return f'<span class="cm">{esc}</span>'
    if stripped.startswith("·"):
        return f'<span class="kw">{esc}</span>'
    return TOKEN.sub(
        lambda m: f'<span class="{cls(m.group())}">{m.group()}</span>', esc)


def find_range(lines, spec):
    first = spec["first"].strip()
    last = spec["last"].strip()
    start = next((i for i, l in enumerate(lines) if l.strip() == first), None)
    if start is None:
        raise SystemExit(f"{spec['file']}: anchor line not found: {first!r}")
    end = next((i for i in range(start, len(lines)) if lines[i].strip() == last), None)
    if end is None:
        raise SystemExit(f"{spec['file']}: closing line not found after the anchor: {last!r}")
    if spec["end_blank"]:
        end += 1
        if end >= len(lines) or lines[end].strip():
            raise SystemExit(f"{spec['file']}: expected a blank line after {last!r}")
    return start, end


def source_lines(spec):
    return (SRC / spec["file"]).read_text(encoding="utf-8").splitlines()


def render_cell(tag, spec, commit):
    lines = source_lines(spec)
    start, end = find_range(lines, spec)
    readings = [list(r) for r in READINGS[tag]]
    body = []
    speech = []
    for n in range(start, end + 1):
        line = lines[n]
        body.append(f'<div class="cline"><span class="ln">{n + 1}</span>'
                    f'<span class="code">{highlight(line)}</span></div>')
        match = next((r for r in readings if r[0] == line.strip()), None)
        if match is not None:
            readings.remove(match)
            body.append(f'<div class="read"><span class="ln"></span>'
                        f'<span class="rtext">{html.escape(match[1], quote=False)}</span></div>')
            speech.append(match[1])
    for orphan in readings:
        print(f"warning: {tag}: reading no longer anchored: {orphan[0]!r}", file=sys.stderr)
    text = " ".join(speech)
    return (f'<section class="cell codecell" id="cell-{tag}">\n'
            f'  <div class="codehead">\n'
            f'    <a class="tag" href="#ref-{tag}" title="jump to the reference entry">[{tag}]</a>\n'
            f'    <span class="loc">{spec["file"]}:{start + 1}–{end + 1}</span>\n'
            f'    <button class="speak" data-tag="{tag}">speak</button>\n'
            f'  </div>\n'
            f'  <div class="codebody">{"".join(body)}</div>\n'
            f'  <script type="application/json" class="speech" id="speech-{tag}">'
            f'{json.dumps(text)}</script>\n'
            f'</section>')


def render_refs(commit):
    rows = []
    for kind, key in ORDER:
        if kind != "cell":
            continue
        spec = CELLS[key]
        rel = f"formal/uvrr-lean/UVRR/{spec['file']}"
        start, end = find_range(source_lines(spec), spec)
        rows.append(f'<tr id="ref-{key}"><td class="tag">[{key}]</td>'
                    f'<td><a href="file://{ROOT}/{rel}" title="{rel} @ {commit} (repo HEAD)">{rel}</a></td>'
                    f'<td class="ln2">{start + 1}–{end + 1}</td>'
                    f'<td class="cm2">{commit}</td></tr>')
    return (f'<h2>References</h2>\n<table class="refs">\n'
            f'<tr><td class="tag">[tag]</td><td>path (click to open the file)</td>'
            f'<td>lines</td><td>commit</td></tr>\n{"".join(rows)}\n</table>')


def build():
    commit = subprocess.run(["git", "rev-parse", "--short", "HEAD"], cwd=ROOT,
                            capture_output=True, text=True, check=True).stdout.strip()
    blocks = []
    for i, (kind, key) in enumerate(ORDER):
        if kind == "note":
            blocks.append(GAPS[i] + NOTE_BLOCKS[key])
        elif kind == "fig":
            blocks.append(GAPS[i] + FIGURE_BLOCKS[key])
        else:
            blocks.append(GAPS[i] + render_cell(key, CELLS[key], commit))
    toc = ' · '.join(f'<a href="#cell-{t}">[{t}]</a>' for t in CELLS)
    parts = [HEAD, f'<div class="sub">{SUB.format(commit=commit)}</div>\n',
             f'<div class="toc">Spine: {toc}</div>\n']
    parts += blocks
    parts += [TAIL_GAP, render_refs(commit),
              f'\n<footer>{FOOTER.format(commit=commit)}</footer>\n</main>\n',
              SCRIPT_BLOCK]
    OUT.write_text("".join(parts), encoding="utf-8")
    print(f"wrote {OUT.relative_to(ROOT)}")


if __name__ == "__main__":
    build()
